import { v4 as uuidv4 } from 'uuid';
import { ITrackEventFn, ITrackEventFnParam } from './TrackingService.interfaces';

// Below function is copied over from - https://cd.splunkdev.com/eui/splunkcore-web-ui/-/blob/develop/web/build_tools/profiles/telemetry/index.js
// There is a bug where swa.js will not send an event if swa.js is not yet loaded.
// When the swa.js is finished loading, it is an object (SPL-211704).
const trackEventTelemetry: ITrackEventFn = (event) => {
    const swaJSCheckInterval = setInterval(() => {
        // eslint-disable-next-line no-underscore-dangle
        if (!window._splunk_metrics_events || Array.isArray(window._splunk_metrics_events)) {
            return;
        }
        clearInterval(swaJSCheckInterval);
        // eslint-disable-next-line no-underscore-dangle
        window._splunk_metrics_events.push(event);
    }, 500);
};

class TrackingServiceSingleton {
    private sessionId: string = uuidv4();

    private timeSinceLastInteraction: number = new Date().getTime();

    private pageLoaded: string;

    // used to keep a log of all the events that were sent to the Telemetry service.
    private trackingLog: ITrackEventFnParam[] = [];

    public trackEvent: ITrackEventFn = ({ type, data }) => {
        if (type === 'manageConfigPage.load') {
            // cache the name of the loaded page to pass it on every subsequent request
            this.pageLoaded = (data.pageLoaded as string) || '';
        }
        const currTimestamp = new Date().getTime();

        const payload: ITrackEventFnParam = {
            type,
            data: {
                ...data,
                trackingSvcCurrPage: this.pageLoaded,
                trackingSvcSessionId: this.sessionId,
                trackingSvcDeltaTime: `${(currTimestamp - this.timeSinceLastInteraction) / 1000} seconds`,
            },
        };
        this.timeSinceLastInteraction = currTimestamp;

        this.trackingLog.push(payload);
        trackEventTelemetry(payload);
    };

    public getTrackingLogs = (): ITrackEventFnParam[] => this.trackingLog;
}

export const TrackingService = new TrackingServiceSingleton();
