import { get } from 'lodash';
import { findErrorMessage } from '@splunk/splunk-utils/fetch';
import { createURL } from '@splunk/splunk-utils/url';
import { IValidateState } from '@splunk/sui-form-renderer';
import { $any } from '../../app.interfaces';
import { MESSAGES } from '../../messages';
import ERRORS_CODES from './errors';

import {
    AVAILABLE_OBJECT_PREFIX,
    CONTROL_GROUP_LABEL_WIDTH,
    CONTROL_GROUP_MAX_WIDTH,
    DEFAULT_WINPUT_APP_NAME_PREFIX,
} from '../../constants';

const IPv4Format = /^([0-9]{1,3}\.){3}[0-9]{1,3}(\/([0-9]|[1-2][0-9]|3[0-2]))?$/;
const IPv4CidrFormat = /^([0-9]{1,3}\.){3}[0-9]{1,3}(\/([0-9]|[1-2][0-9]|3[0-2]))?$/;
const IPv6Format =
    /^(([0-9A-Fa-f]{1,4}:){7}([0-9A-Fa-f]{1,4}|:))|(([0-9A-Fa-f]{1,4}:){6}(:[0-9A-Fa-f]{1,4}|((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3})|:))|(([0-9A-Fa-f]{1,4}:){5}(((:[0-9A-Fa-f]{1,4}){1,2})|:((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3})|:))|(([0-9A-Fa-f]{1,4}:){4}(((:[0-9A-Fa-f]{1,4}){1,3})|((:[0-9A-Fa-f]{1,4})?:((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}))|:))|(([0-9A-Fa-f]{1,4}:){3}(((:[0-9A-Fa-f]{1,4}){1,4})|((:[0-9A-Fa-f]{1,4}){0,2}:((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}))|:))|(([0-9A-Fa-f]{1,4}:){2}(((:[0-9A-Fa-f]{1,4}){1,5})|((:[0-9A-Fa-f]{1,4}){0,3}:((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}))|:))|(([0-9A-Fa-f]{1,4}:){1}(((:[0-9A-Fa-f]{1,4}){1,6})|((:[0-9A-Fa-f]{1,4}){0,4}:((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}))|:))|(:(((:[0-9A-Fa-f]{1,4}){1,7})|((:[0-9A-Fa-f]{1,4}){0,5}:((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}))|:))$/;
const ERROR_URL = createURL('/error');

export const isIpV4Cidr = (value: string): boolean => {
    if (!IPv4CidrFormat.test(value)) {
        return false;
    }
    // the IPv4CidrFormat regex makes no assumptions about validity of IP octets
    // so we check them here separately
    const [ip] = value.split('/');
    const octets = ip.split('.');
    // "octet <= 255" is the only check we have to do
    // because other constraints are guaranteed by
    // the regex itself
    const octetValidities = octets.map((octet) => parseInt(octet, 10) <= 255);
    return octetValidities.every((x) => x);
};

export const isIpV6Cidr = (value: string): boolean => {
    const chunks = value.split('/');
    if (chunks.length === 1) {
        return IPv6Format.test(chunks[0]);
    }
    if (chunks.length === 2) {
        const address = chunks[0];
        const port = parseInt(chunks[1], 10);
        return IPv6Format.test(address) && !Number.isNaN(port) && port >= 0 && port <= 128;
    }
    return false;
};

const getDefaultValidateState = (): IValidateState => {
    return {
        isValid: true,
        error: '',
    };
};

export const validateCidr = (value: string): IValidateState => {
    const isValid = isIpV4Cidr(value) || isIpV6Cidr(value);
    return {
        isValid,
        error: isValid ? '' : 'Invalid Subnet',
    };
};

export const validateIPAddress = (value: string): IValidateState => {
    const isValid = IPv4Format.test(value);
    return {
        isValid,
        error: isValid ? '' : 'Invalid Subnet',
    };
};

export const validateWebhookDomainKey = (value: string): IValidateState => {
    const validDomainKeyRegex = /^\w+$/;
    if (value === '') {
        return {
            isValid: false,
            error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.REQUIRED_FIELD],
        };
    }
    if (!validDomainKeyRegex.test(value)) {
        return {
            isValid: false,
            error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.LETTERS_NUMBERS_UNDERSCORE_ALLOWED],
        };
    }
    return getDefaultValidateState();
};

export const validateWebhookDomainFormat = (value: string): IValidateState => {
    try {
        /* eslint-disable no-new */
        if (value === '') {
            return {
                isValid: false,
                error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.REQUIRED_FIELD],
            };
        }
        new RegExp(value);
        return getDefaultValidateState();
    } catch (e) {
        return {
            isValid: false,
            error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.WEBHOOK_DOMAIN_FORMAT_INVALID],
        };
    }
};

export const validateDashboardUrlKey = (value: string): IValidateState => {
    if (value === '') {
        return {
            isValid: false,
            error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.REQUIRED_FIELD],
        };
    }
    // Allow only keys that have no whitespace or special characters.
    const validUrlKeyRegex = /^\w+$/;
    if (!validUrlKeyRegex.test(value)) {
        return {
            isValid: false,
            error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.LETTERS_NUMBERS_UNDERSCORE_ALLOWED],
        };
    }
    return getDefaultValidateState();
};

export const validateDashboardUrlFormat = (value: string): IValidateState => {
    // URL must not be empty
    if (value === '') {
        return {
            isValid: false,
            error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.REQUIRED_FIELD],
        };
    }

    // URL must not contain spaces
    if (!value.includes(' ')) {
        return getDefaultValidateState();
    }

    // Otherwise, it is invalid
    return {
        isValid: false,
        error: MESSAGES.UTIL_ERRORS.ERRORS[ERRORS_CODES.INVALID_URL],
    };
};

export const constructServerSettingsURL = (): string => {
    const url = get(window, 'location.href', '') as string;
    return url ? url.replace(/manage_system_config.*/, 'systemsettings') : '';
};

export const isDevEnv = (): boolean => process.env.NODE_ENV === 'development';

export const isStaging = (): boolean => {
    const hostname = window.location.host;
    return hostname.endsWith('stg.splunkcloud.com') || hostname.startsWith('localhost');
};

export const setErrorPage = (): void => {
    // The default splunk page lives in splcore and has not been packaged as a consumable component.
    // This is a workaround to load the default splunk error page.
    const currentUrl = window.location.href;
    window.history.pushState({}, '', currentUrl);
    window.location.assign(ERROR_URL);
};

export const filterErrorMessages = (errors: string[]): string[] => errors.filter((error) => !!error);

export const getControlGroupLabelWidthProps = (): $any => ({
    labelWidth: CONTROL_GROUP_LABEL_WIDTH,
    style: {
        maxWidth: CONTROL_GROUP_MAX_WIDTH,
    },
});

export const getAlwaysDisableElementRule = (): $any => ({
    effect: 'DISABLE',
    condition: {
        scope: '#',
        schema: {},
    },
});

/*
 * getHideElementsRule() returns a rule for hiding a UI element based on the combination of
 * propertyName (corresponds to the UI element) & propertyValue (corresponds to the UI element's value)
 * based on which we want to a HIDE a UI element
 * */
export const getHideElementsRule = ({
    propertyName,
    propertyValue,
}: {
    propertyName: string;
    propertyValue: string;
}): $any => ({
    effect: 'HIDE',
    condition: {
        scope: `#/properties/${propertyName}`,
        schema: { enum: [propertyValue] },
    },
});

// Helper function to parse a splunkd error response
export const formatSplunkDError = (splunkdJson: $any): string => {
    const errorMessage = findErrorMessage(splunkdJson);
    return errorMessage?.text || MESSAGES.COMMON.DEFAULT_ERROR_MSG;
};

// Winput APIs have a required arg called app_name that is a combo of the
// DEFAULT_WINPUT_APP_NAME_PREFIX and the entity
export const formatWinputAppName = (entity: string): string => {
    return `${DEFAULT_WINPUT_APP_NAME_PREFIX}${entity}`;
};

// Available objects returned from REST contains a prefix. In the original code, this prefix
// is stripped before displaying on the UI.
export const stripAvailableObjectsPrefix = (availableObject: string): string => {
    return availableObject.startsWith(AVAILABLE_OBJECT_PREFIX)
        ? availableObject.slice(AVAILABLE_OBJECT_PREFIX.length)
        : availableObject;
};

// Apply prefix to the availableObject before sending request to SplunkD
export const formatAvailableObject = (availableObject: string): string => {
    return `${AVAILABLE_OBJECT_PREFIX}${availableObject}`;
};
