import React, { FC, useEffect, useState, lazy, Suspense } from 'react';
import Code from '@splunk/react-ui/Code';
import SplunkThemeProvider from '@splunk/themes/SplunkThemeProvider';
import styled from 'styled-components';

import { findConfigPage } from '../shared/utils/ConfigPageURL/ConfigPageURL';
import { Pages, PagesType } from '../app.interfaces';
import { MessageContext } from './context/message-context';
import { Message } from './message/Message.component';
import TopBanner from './top-banner';
import { TrackingService } from '../shared/services/TrackingService';
import { setErrorPage } from '../shared/utils/helper';
import { ServerInfoService } from '../shared/services/ServerInfoService';
import { UserContextService } from '../shared/services/UserContextService';
import { ExperienceService } from '../shared/services/ExperienceService';
import { MESSAGES } from '../messages';

import '../global.css';

const DashboardsTrustedDomainsList = lazy(() => import('./dashboards-trusted-domains-list'));
const IPAllowList = lazy(() => import('./ip-allow-list'));
const LimitsConfig = lazy(() => import('./limits-config'));
const WebhookAllowList = lazy(() => import('./webhook-allow-list'));
const WinEventLogCollections = lazy(() => import('./win-event-log-collections'));
const WinFwdPerfmon = lazy(() => import('./win-fwd-perfmon'));
const WinPerfmon = lazy(() => import('./win-perfmon'));
const WinWmiCollections = lazy(() => import('./win-wmi-collections'));

const LoadingWrapper = styled.div`
    text-align: center;
    margin-top: 100px;
`;

const ConfigPage: FC = () => {
    const [isTrackingLogVisible, setIsTrackingLogVisible] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const configPage = findConfigPage();

    useEffect(() => {
        const init = async (): Promise<void> => {
            try {
                await Promise.all([
                    ServerInfoService.init(),
                    UserContextService.init(),
                    ExperienceService.init(),
                ]);
            } catch (err) {
                console.error(err);
                setErrorPage();
            } finally {
                setIsLoading(false);
            }
        };
        init();
    }, []);

    useEffect(() => {
        TrackingService.trackEvent({
            type: 'manageConfigPage.load',
            data: {
                pageLoaded: configPage.name,
            },
        });
        const dblClickHandler = (event): void => {
            if (event.shiftKey && event.altKey) {
                setIsTrackingLogVisible((prevValue) => !prevValue);
            }
        };
        window.addEventListener('dblclick', dblClickHandler);

        return (): void => window.removeEventListener('dblclick', dblClickHandler);
    }, [configPage]);

    const Loading: FC = () => <LoadingWrapper>{MESSAGES.COMMON.LOADING_MSG}</LoadingWrapper>;
    if (isLoading) {
        return <Loading />;
    }

    return (
        <SplunkThemeProvider family="enterprise" colorScheme="light">
            <MessageContext.Provider value={{ type: 'success', message: null }}>
                <TopBanner configPage={configPage.name as PagesType} />
                <Message />
                <Suspense fallback={<Loading />}>
                    {configPage.name === Pages.DashboardsTrustedDomainsList && (
                        <DashboardsTrustedDomainsList />
                    )}
                    {configPage.name === Pages.IPAllowList && <IPAllowList />}
                    {configPage.name === Pages.LimitsConfig && <LimitsConfig />}
                    {configPage.name === Pages.WebhookAllowList && <WebhookAllowList />}
                    {configPage.name === Pages.WinEventLogCollections && (
                        <WinEventLogCollections entity={configPage.entity} />
                    )}
                    {configPage.name === Pages.WinFwdPerfmon && <WinFwdPerfmon entity={configPage.entity} />}
                    {configPage.name === Pages.WinPerfmon && <WinPerfmon entity={configPage.entity} />}
                    {configPage.name === Pages.WinWmiCollections && (
                        <WinWmiCollections entity={configPage.entity} />
                    )}

                    {isTrackingLogVisible && (
                        <Code
                            value={JSON.stringify(TrackingService.getTrackingLogs(), null, 4)}
                            language="json"
                        />
                    )}
                </Suspense>
            </MessageContext.Provider>
        </SplunkThemeProvider>
    );
};

export default ConfigPage;
