import { defaultFetchInit, handleResponse } from '@splunk/splunk-utils/fetch';
import { createRESTURL } from '@splunk/splunk-utils/url';
import { SplunkExperienceTypes } from '../../../app.interfaces';

class ExperienceServiceSingleton {
    private isInitialized = false;

    private dmcTopologyUrl = createRESTURL('dmc/topologies');

    private experienceType: SplunkExperienceTypes = 'noah';

    public init = async (): Promise<void> => {
        if (this.isInitialized) {
            return;
        }

        await this.fetchDMCTopology();

        this.isInitialized = true;
    };

    private fetchDMCTopology = async (): Promise<void> => {
        try {
            const response = await fetch(this.dmcTopologyUrl, { ...defaultFetchInit });
            await handleResponse(200)(response);
            this.experienceType = 'classic';
        } catch (err) {
            // Errors mean the server is Noah
            this.experienceType = 'noah';
        }
    };

    public getExperienceType = (): SplunkExperienceTypes => {
        return this.experienceType;
    };
}

export const ExperienceService = new ExperienceServiceSingleton();
