import { IFormData } from '@splunk/config-form-generator';

/*
 * List of limits.conf stanzas managed by ACUIF
 */
export enum LimitsConfigStanzaValues {
    JOIN = 'join',
    KV = 'kv',
    SUBSEARCH = 'subsearch',
    SCHEDULER = 'scheduler',
    SPATH = 'spath',
    PDF = 'pdf',
    SEARCHRESULTS = 'searchresults',
}
/*
 * List of limits.conf fields managed by ACUIF
 */
export enum LimitsConfigJoinFieldValues {
    SUBSEARCH_MAXOUT = 'subsearch_maxout',
    SUBSEARCH_MAXTIME = 'subsearch_maxtime',
}
export enum LimitsConfigKVFieldValues {
    LIMIT = 'limit',
    MAXCHARS = 'maxchars',
    MAXCOLS = 'maxcols',
}
export enum LimitsConfigSubsearchFieldValues {
    MAXOUT = 'maxout',
    MAXTIME = 'maxtime',
}
export enum LimitsConfigSchedulerFieldValues {
    MAX_PER_RESULT_ALERTS = 'max_per_result_alerts',
    MAX_PER_RESULT_ALERTS_TIME = 'max_per_result_alerts_time',
}
export enum LimitsConfigSPathFieldValues {
    EXTRACTION_CUTOFF = 'extraction_cutoff',
}
export enum LimitsConfigPDFFieldValues {
    MAX_ROWS_PER_TABLE = 'max_rows_per_table',
}
export enum LimitsConfigSearchResultsFieldValues {
    MAXRESULTROWS = 'maxresultrows',
}
export type LimitsConfigFieldValues =
    | LimitsConfigJoinFieldValues
    | LimitsConfigKVFieldValues
    | LimitsConfigSubsearchFieldValues
    | LimitsConfigSchedulerFieldValues
    | LimitsConfigSPathFieldValues
    | LimitsConfigPDFFieldValues
    | LimitsConfigSearchResultsFieldValues;

export type LimitsConfigSettings = {
    setting: string;
    minValue: number;
    maxValue: number;
    defaultValue: number;
};
export type LimitsConfigDefault = {
    stanza: string;
    settings: LimitsConfigSettings[];
};
export type LimitsConfigDefaults = LimitsConfigDefault[];

export type LimitsConfigStanza = {
    Stanza: string;
    Values: object;
};
export type LimitsConfigStanzas = LimitsConfigStanza[];

/*
 * Required params for UpdateStanza function
 */
export interface UpdateStanzaParams {
    stanza: LimitsConfigStanzaValues;
    settings: Record<string, string | number>;
}

/*
 * Output of helper function handleACSResponse(), which parses the ACS API response.
 * Only some ACS responses contain JSON. For those that do not, we return true.
 */
export type ParsedACSResponse =
    | Record<string, never>
    | LimitsConfigDefaults
    | LimitsConfigStanzas
    | ACSJson
    | ACSErrorJson;
export interface ACSJson {
    stanzas: LimitsConfigStanzas;
}
export interface ACSErrorJson {
    message: string;
}

/*
 * Required params for fetchLimitsConfig function
 */
export interface FetchLimitsConfigParams {
    stanza: string;
}

export interface ILimitsConfigFnReturnType {
    records?: IFormData;
    error?: string[];
}
