import { get } from 'lodash';
import { defaultFetchInit, handleResponse } from '@splunk/splunk-utils/fetch';
import { createRESTURL } from '@splunk/splunk-utils/url';
import { MESSAGES } from '../../../messages';
import ERRORS_CODES from '../UserService/errors';

class UserContextServiceSingleton {
    private isInitialized = false;

    private userContextUrl = createRESTURL('authentication/current-context?output_mode=json');

    private optInRemoteUIUrl = createRESTURL('properties/web/remoteUI/optInRemoteUI');

    private userContext = {};

    public init = async (): Promise<void> => {
        if (this.isInitialized) {
            return;
        }
        await this.fetchUserContext();

        this.isInitialized = true;
    };

    private fetchUserContext = async (): Promise<void> => {
        try {
            const response = await fetch(this.userContextUrl, { ...defaultFetchInit });
            const json = await handleResponse(200)(response);
            this.userContext = get(json, 'entry[0].content', '');
        } catch (err) {
            throw new Error('Unable to fetch user context');
        }
    };

    public canReadPage = (capabilities): boolean => {
        const allCapabilities = new Set(get(this.userContext, 'capabilities', []));
        return capabilities.every((capability) => allCapabilities.has(capability));
    };

    public getCurrUsername = (): string => {
        return get(this.userContext, 'username');
    };

    public fetchOptInRemoteUIFlag = async (): Promise<boolean> => {
        try {
            const response = await fetch(this.optInRemoteUIUrl, { ...defaultFetchInit });
            return await handleResponse(200)(response);
        } catch (err) {
            throw new Error(MESSAGES.USER_CONTEXT.ERRORS[ERRORS_CODES.FETCH_OPT_IN_REMOTE_UI_NOT_FOUND]);
        }
    };
}

export const UserContextService = new UserContextServiceSingleton();
