import queryString from 'query-string';
import Url from 'url-parse';
import type URLParse from 'url-parse';
import { Pages } from '../../../app.interfaces';
import { ConfigPageObj } from './ConfigPageURL.interfaces';

export const supportedPages = new Set([
    Pages.DashboardsTrustedDomainsList,
    Pages.IPAllowList,
    Pages.LimitsConfig,
    Pages.WebhookAllowList,
    Pages.WinEventLogCollections,
    Pages.WinFwdPerfmon,
    Pages.WinPerfmon,
    Pages.WinWmiCollections,
]);

/**
 * Parses URL to find the a valid config page. If no valid page is found,
 * take the user to Server Settings screen. Also parses querystring params
 * for pages that require it.
 * @returns @type/ConfigPageObj - The name of the matching Config page
 */
export const findConfigPage = (): ConfigPageObj => {
    const url: URLParse<string> = new Url(window.location.href);

    const pageNameRegex = /(?<=\/manage_system_config\/)([a-z_]*)/g;
    const pageNameMatch = url.href.match(pageNameRegex);
    const pageName = pageNameMatch?.length ? pageNameMatch[0] : '';
    const queryArgs = queryString.parse(url.query);

    // Redirect to systemsettings if page does not exist
    if (!supportedPages.has(pageName as Pages)) {
        const beforeManageSysCfgRegex = /^.*(?=(\/manage_system_config))/g;
        const baseUrlMatch = url.href.match(beforeManageSysCfgRegex);

        const baseUrl = baseUrlMatch?.length ? baseUrlMatch[0] : '';
        const redirectUrl = baseUrl.concat('/systemsettings');
        window.location.href = redirectUrl as string;
        return null;
    }

    const configPage = { name: pageName as Pages };

    // Only parse querystring for entity and ignore the rest
    if ('entity' in queryArgs) {
        configPage['entity' as string] = queryArgs.entity;
    }

    return configPage;
};
