import React, { FC } from 'react';
import Heading from '@splunk/react-ui/Heading';
import Link from '@splunk/react-ui/Link';
import P from '@splunk/react-ui/Paragraph';
import styled from 'styled-components';

import { MESSAGES } from '../../messages';
import { ConfigPages, PagesType, WinputsPages } from '../../app.interfaces';
import { constructDataInputStatsUrl, constructServerSettingsURL } from '../../shared/utils/helper';

const WrapperDiv = styled.div`
    padding: 20px;
`;

const PageTitle = styled(Heading)`
    margin-top: 0px;
`;

interface IProps {
    configPage: PagesType;
}

const genBreadcrumbLink = (configPage: PagesType): React.ReactElement => {
    let href = '';
    let breadcrumbLabel = '';
    const serverSettingsPages = Object.values(ConfigPages);
    const winputsPages = Object.values(WinputsPages);
    if (serverSettingsPages.includes(configPage)) {
        href = constructServerSettingsURL();
        breadcrumbLabel = MESSAGES.COMMON.SERVER_SETTINGS_BREADCRUMB_LABEL;
    } else if (winputsPages.includes(configPage)) {
        href = constructDataInputStatsUrl();
        breadcrumbLabel = MESSAGES.COMMON.DATA_INPUTS_BREADCRUMB_LABEL;
    }
    return <Link to={href}>{breadcrumbLabel}</Link>;
};

const TopBanner: FC<IProps> = ({ configPage }) => {
    return (
        <WrapperDiv>
            <PageTitle level={1}>{MESSAGES.PAGE_TITLES[configPage]}</PageTitle>
            <P>
                {genBreadcrumbLink(configPage)}
                {` » ${MESSAGES.PAGE_TITLES[configPage]}`}
            </P>
        </WrapperDiv>
    );
};

export default TopBanner;
