type IIPRecord = string[];

/*
 * List of feature managed by ACS API IP Allow Lists
 */
export enum FeatureType {
    HEC = 'hec',
    S2S = 's2s',
    SearchAPI = 'search-api',
    SearchUI = 'search-ui',
    IDMAPI = 'idm-api',
    IDMUI = 'idm-ui',
}

export enum IPProtocol {
    v4,
    v6,
}

/*
 * Subnet IP Addresses in CIDR format
 */
export type Subnets = string[];
/*
 * Required params for addDelSubnet function
 */
export interface AddDelSubnetParams {
    protocol: IPProtocol;
    feature: FeatureType;
    subnets: Subnets;
    method: 'post' | 'delete';
}
/*
 * Required params for fetchIPAllowList function
 */
export interface FetchIPAllowListParams {
    feature: FeatureType;
    protocol: IPProtocol;
}
/*
 * Output of helper function handleACSResponse(), which parses the ACS API response.
 * Only some ACS responses contain JSON. For those that do not, we return true.
 */
export type ParsedACSResponse = Record<string, never> | ACSJson | ACSErrorJson;
export interface ACSJson {
    subnets: Subnets;
}
export interface ACSErrorJson {
    message: string;
}

interface IIPAllowListFormDataAllRequired {
    [FeatureType.SearchAPI]: IIPRecord;
    [FeatureType.HEC]: IIPRecord;
    [FeatureType.S2S]: IIPRecord;
    [FeatureType.SearchUI]: IIPRecord;
    [FeatureType.IDMUI]: IIPRecord;
    [FeatureType.IDMAPI]: IIPRecord;
}

// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface IIPAllowListFormData extends Partial<IIPAllowListFormDataAllRequired> {}

interface IGenerateDiffFnParam {
    prevSubnets: string[];
    currSubnets: string[];
}
export interface IGenerateDiffFn {
    (param: IGenerateDiffFnParam): { added: string[]; removed: string[] };
}

export interface IIPAllowListFnReturnType {
    records?: IIPAllowListFormData;
    error?: string[];
}

export interface IParsedIPAllowlistFeatureResponse {
    enable_ipv6_validations: boolean; // eslint-disable-line camelcase
}
