import { get } from 'lodash';
import { defaultFetchInit, handleResponse } from '@splunk/splunk-utils/fetch';
import { createRESTURL } from '@splunk/splunk-utils/url';
import { ServerInfoJSON } from './ServerInfoService.interface';
import { SplunkInstanceTypes } from '../../../app.interfaces';

class ServerInfoServiceSingleton {
    private isInitialized = false;

    private serverInfoUrl = createRESTURL('server/info/server-info?output_mode=json');

    private serverInfo: ServerInfoJSON = {};

    public init = async (): Promise<void> => {
        if (this.isInitialized) {
            return;
        }

        await this.fetchServerInfo();

        this.isInitialized = true;
    };

    private fetchServerInfo = async (): Promise<void> => {
        try {
            const response = await fetch(this.serverInfoUrl, { ...defaultFetchInit });
            const json = await handleResponse(200)(response);
            this.serverInfo = get(json, 'entry[0].content', {});
        } catch (err) {
            throw new Error('Unable to fetch server info');
        }
    };

    public getOS = (): string => {
        return this.serverInfo.os_name || '';
    };

    public getSplunkInstanceType = (): SplunkInstanceTypes => {
        // instance_type is only set in Splunk Cloud at provision time. If it is not set,
        // we assume that the deployment is CMP.
        if (this.serverInfo.instance_type === 'cloud') {
            return this.serverInfo.instance_type;
        }
        return 'cmp';
    };
}

export const ServerInfoService = new ServerInfoServiceSingleton();
